/// <summary>
/// MPJ_11539 - kscerri - 27/07/2021
/// Class <c>METCustTransListingDP</c> data provider
/// </summary>
[
    SRSReportQueryAttribute(queryStr(METCustActivityStatementData)),
    SRSReportParameterAttribute(classstr(METCustActivityStatementContract))
]
class METCustActivityStatementDP extends SrsReportDataProviderPreProcessTempDB
{
    // Contains payment data
    METCustActivityStatementTmp             custTransListingTmp;
    METCustActivityStatementInvoiceLinesTmp custActivityStatementInvoiceLinesTmp;
    METCustActivityStatementContract        contract;

    METCustActivityStatementTmp             custActivityStatementHeader;
    METCustActivityStatementInvoiceLinesTmp custActivityStatementLines;

}

Method.Source:
/// <summary>
/// MPJ_11539 - kscerri - 08/04/2021
/// Header tmp table
/// </summary>
/// <returns>tmp table</returns>
[SRSReportDataSetAttribute(tablestr(METCustActivityStatementTmp))]
public METCustActivityStatementTmp getHeader()
{
    select custTransListingTmp;
    return custTransListingTmp;
}

/// <summary>
/// MPJ_11539 - kscerri - 08/04/2021
/// Invoice lines tmp table
/// </summary>
/// <returns>tmp table</returns>
[SRSReportDataSetAttribute(tablestr(METCustActivityStatementInvoiceLinesTmp))]
public METCustActivityStatementInvoiceLinesTmp getInvoiceLines()
{
    select custActivityStatementInvoiceLinesTmp;
    return custActivityStatementInvoiceLinesTmp;
}

    /// <summary>
    /// MPJ_11539 - kscerri - 08/04/2021
    /// Process report data.
    /// </summary>
    public void processReport()
    {
        contract = this.parmDataContract() as METCustActivityStatementContract;

        //Set the correct tmpDB table instance to use
        custActivityStatementHeader.useExistingTempDBTable(contract.parmCustActivityStatementHeader());
        
        this.insertNewRecordsHeader(custActivityStatementHeader, contract.parmHeaderRecordId());
        
        custActivityStatementLines.useExistingTempDBTable(contract.parmCustActivityStatementLines());

        this.insertNewRecordsLines(custActivityStatementLines ,contract.parmRecordId());

    }

/// <summary>
/// Insert Header records into temp table
/// </summary>
/// <param name = "_custActivityStatementHeader">Temp table</param>
/// <param name = "_statementRecId">Created transaction Id</param>
public void insertNewRecordsHeader(METCustActivityStatementTmp _custActivityStatementHeader, RecId _statementRecId)
{
    while select _custActivityStatementHeader
        where _custActivityStatementHeader.CreatedTransactionId == _statementRecId
        {
            buf2Buf(_custActivityStatementHeader, custTransListingTmp);
            custTransListingTmp.insert();
        }
}

    /// <summary>
    /// Insert Transaction records into temp table
    /// </summary>
    /// <param name = "_custActivityStatementLines">Temp table</param>
    /// <param name = "_statementRecId">Created transaction Id</param>
    public void insertNewRecordsLines(METCustActivityStatementInvoiceLinesTmp _custActivityStatementLines, RecId _statementRecId)
    {
        
        insert_recordset custActivityStatementInvoiceLinesTmp (AccountNum, TransDate, Txt, PaymReference, Invoice, AmountCur, TransType, GST, TaxAmountCur, Flag, AccountName, DueDate)

            select AccountNum, TransDate, Txt, PaymReference, Invoice, AmountCur, TransType, GST, TaxAmountCur, Flag, AccountName, DueDate
            from _custActivityStatementLines    
            order by AccountNum asc
            where _custActivityStatementLines.CreatedTransactionId == _statementRecId;
        
    }
